 set("play",1);for(int i=0;i<100;++i){buffer.clear();p->processBlock(buffer,midi);}p->getStateInformation(saved);std::unique_ptr<Processor> q(static_cast<Processor*>(createPluginFilter()));q->setStateInformation(saved.getData(),int(saved.getSize()));q->prepareToPlay(48000,64);bool same=true;for(int b=0;b<3;++b)same&=q->engine.motion.ball[b].x==p->engine.motion.ball[b].x&&q->engine.motion.ball[b].y==p->engine.motion.ball[b].y;check(same,"Pong positions restored from host state");AudioBuffer<float> qb(2,64);for(int i=0;i<100;++i){buffer.clear();qb.clear();p->processBlock(buffer,midi);q->processBlock(qb,midi);}same=true;for(int b=0;b<3;++b)same&=q->engine.motion.ball[b].x==p->engine.motion.ball[b].x&&q->engine.motion.ball[b].y==p->engine.motion.ball[b].y;check(same,"restored Pong simulation continues deterministically");
 std::unique_ptr<AudioProcessorEditor> editor(p->createEditor());auto click=[&](const String& title){for(int n=0;n<editor->getNumChildComponents();++n)if(auto*b=dynamic_cast<TextButton*>(editor->getChildComponent(n)))if(b->getButtonText()==title){b->onClick();return;}};click("PONG DEMO");for(int i=0;i<1000;++i){for(int n=0;n<64;++n){buffer.setSample(0,n,.2f*std::sin((i*64+n)*.08f));buffer.setSample(1,n,.2f*std::sin((i*64+n)*.07f));buffer.setSample(2,n,0);}p->processBlock(buffer,midi);}
 const char* titles[]{"PONG / PLAY","MODULES","ADAPTIVE MATRIX","PLATE / GLUE / LIMIT"};for(int page=0;page<4;++page){click(titles[page]);auto img=editor->createComponentSnapshot(editor->getLocalBounds());auto image=File::getCurrentWorkingDirectory().getChildFile("PongDynamics-v2-page"+String(page)+".png");image.deleteFile();auto out=image.createOutputStream();PNGImageFormat png;check(out&&png.writeImageToStream(img,*out),"GUI page rendered");}
 editor.reset();std::cout<<"Failures: "<<fails<<"\n";return fails?1:0;
